oh = pd.read_csv('don_hang.csv')
def parse_date(s):
    s=str(s).strip()
    for fmt in ("%d/%m/%Y","%d %b %Y","%d %B %Y"):
        try:
            return datetime.strptime(s,fmt).date()
        except: pass
    return None
oh['d']=oh['NgayBan'].map(parse_date)
print(oh['d'].isna().sum(),"unparsed")
print(oh['NgayBan'].nunique(),"unique date strings")
# show unique formats
import re
samples=oh['NgayBan'].dropna().unique()[:20]
for s in samples: print(repr(s))
"}

