import pandas as pd, re
from datetime import date, timedelta
oh = pd.read_csv('don_hang.csv')
excel_epoch=date(1899,12,30)
def parse_date(s):
    s=str(s).strip()
    if re.match(r'^\d{5,6}$',s):
        return excel_epoch+timedelta(days=int(s))
    for fmt in ("%d/%m/%Y","%d %b %Y","%d %B %Y"):
        try:
            return datetime.strptime(s,fmt).date()
        except: pass
    return None
oh['d']=oh['NgayBan'].map(parse_date)
bad=oh[oh['d'].isna()]
print("total bad:",len(bad))
print(bad['NgayBan'].value_counts().head(30))
print("unique bad samples:")
for s in bad['NgayBan'].dropna().unique()[:30]:
    print(repr(s))
"}

